import React, { useState, useEffect } from "react";
import Layout from "../components/Layout";
import { useParams } from "react-router-dom";
import axios from "axios";
import moment from "moment";
import { DatePicker, message, TimePicker } from "antd";
import { useDispatch, useSelector } from "react-redux";
import {showLoading, hideLoading} from '../redux/features/alertSlice'

const BookingPage = () => {
  const {user} = useSelector(state=>state.user)
  const params = useParams();
  const dispatch = useDispatch();
  const [doctors, setDoctors] = useState([]);
  const [date, setDate] = useState();
  const [time, setTime] = useState();
  const [isAvailable, setIsAvailable] = useState();
  const getUserData = async () => {
    try {
      const res = await axios.post("/api/v1/doctor/getDoctorById", 
        // { doctorId: params.doctorId },
        {token : localStorage.getItem('token'), doctorId:params.doctorId},
        {
          headers: {
            // Authorization: `Bearer ${localStorage.getItem("token")}`,
            Authorization: "Bearer" + localStorage.getItem("token"),
          },
        }
      );
      if (res.data.success) {
        setDoctors(res.data.data);
      }
    } catch (error) {
      console.log(error);
    }
  };


// ==== Availabity function ===

const handleAvailablity = async()=>{
  try{
    dispatch(showLoading())
    const res = await axios.post('/api/v1/user/booking-availability', {
      doctorId: params.doctorId, 
      date:date,
      time:time
    },{
      headers:{
        Authorization: `Bearer ${localStorage.getItem('token')}`
      }
    })
    dispatch(hideLoading())
    if(res.data.success)
    {
      setIsAvailable(true)
      message.success(res.data.message)
    }
    else{
      message.success(res.data.message)
    }
  } catch(error)
  {
    dispatch(hideLoading())
    console.log(error)
  }
}

// ==== Booking function ===

const handleBooking = async()=>{
  try{
    setIsAvailable(true);
    if(!date && !time)
    {
      return alert("Date and time required");
    }
    dispatch(showLoading())
    const res = await axios.post('/api/v1/user/book-appointment', {
      doctorId: params.doctorId, 
      userId: user._id,
      doctorInfo:doctors,
      date:date,
      userInfo:user,
      time:time
    },{
      headers:{
        Authorization: `Bearer ${localStorage.getItem('token')}`
      }
    })
    dispatch(hideLoading())
    if(res.data.success)
    {
      message.success(res.data.message)
    }
  } catch(error)
  {
    dispatch(hideLoading())
    console.log(error)
  }
}

  useEffect(() => {
    getUserData();
  }, []);

  return (
    <Layout>
      <h3>Booking Page</h3>
      <div className="container">
        {doctors && (
          <div>
            <h4>
              Dr.{doctors.firstName} {doctors.lastName}
            </h4>
            <h4>Fees : {doctors.feesPerConsultation}</h4>
            <h4>
              Timings : {doctors.timings && doctors.timings[0]} -{" "} {doctors.timings && doctors.timings[1]}{" "}
            </h4>
            <div className="d-flex flex-column w-50">
              <DatePicker
                className="m-2"
                format="DD-MM-YYYY"
                onChange={(value) =>{
                  // setIsAvailable(false)
                  setDate(moment(value).format("DD-MM-YYYY"))
                }
                }
              />
              <TimePicker
                className="m-2"
                format="HH:mm"
                onChange={(value) =>
                {
                  // setIsAvailable(false)
                  setTime(
                    moment(value).format("HH:mm"))
                }
                }
              />
              <button className="btn btn-primary mt-2" onClick={handleAvailablity}>
                Check Availability
              </button>
              <button className="btn btn-dark mt-2" onClick={handleBooking}>
                Book Now
              </button>
              {/* {!isAvailable && (<button className="btn btn-dark mt-2" onClick={handleBooking}>
                Book Now
              </button>)} */}
            </div>
          </div>
        )}
      </div>
    </Layout>
  );
};

export default BookingPage;

